insert into strategic_topics (code, title, category, synopsis, description, threats, solutions, deadlines, status, source_quote)
values
-- ─── 3.1 Средовое проектирование ─────────────────────────────────────────
(
    'ENVIRONMENT',
    'Средовое проектирование курортной зоны',
    'environment',
    'Курортная зона на 12 км косы должна формироваться как единый ансамбль с климатической адаптацией, а не как сумма отдельных отелей. Без стандартов благоприятной среды каждый объект решает задачу в одиночку — на выходе разнородный результат и упущенные возможности.',
    'Проект расположен на песчаной косе между набережной и озером Сасык, общая длина застраиваемой зоны 12 км. Геометрия линейная (ширина 60-120 м), что осложняет размещение общей инфраструктуры. Среда требует баланса антропогенной нагрузки и природной устойчивости. На текущей стадии Форэскиз каждый из 8 объектов проектируется автономно своим подрядчиком — без общих правил по этажности, масштабу, цветности, связности пляжей и видовых площадок.',
    'Без единых стандартов благоприятной среды (этажность, масштаб, цветность, материалы, связность пространств) проект на стадии Концепции получит набор разнородных решений, не складывающихся в курортный ансамбль. Это снизит инвестиционную привлекательность, потребует переделки на стадии Проект и удорожит работы.',
    'Разработать стандарты благоприятной среды по 9 измерениям ИКГС (управление, архитектура, навигация, ОДИ, СДИ, уличная инфра, доступность, озеленение, благоустройство). Утвердить как обязательный референс для всех 8 проектов. Учесть на стадии перехода в Концепцию.',
    'Применять начиная с входа в Концепцию (окт-ноя 2026)',
    'open',
    'Аналитический отчёт ТЗ-ЮГ, март 2026, раздел 3.1 «Средовое проектирование»'
),
-- ─── 3.2 ТЭО и ДПТ магистральных сетей ───────────────────────────────────
(
    'MAGISTRAL_NETS',
    'ТЭО и ДПТ магистральных сетей',
    'engineering',
    'Концепция магистральных сетей (вода, водоотведение, газ, электрика, ливнёвка, связь) отсутствует. Прокладка возможна только за счёт инвестиционных участков — решение «после» потребует пересмотра уже согласованных проектов отелей.',
    'Линейная инфраструктура — водоснабжение, водоотведение, газоснабжение, электроснабжение, ливневая канализация, телефония, берегоукрепление, пешеходные переходы через ж/д и трассу — на сегодня не имеет проектной концепции. Работы намечены на октябрь 2026 — август 2027. Подрядчики не отбирались, договорная основа не готовится. Юридическое выделение земельных участков под коридоры трасс не выполнено.',
    'Если коридоры магистралей не определены до Концепции отелей — изменения границ участков, удорожание подключений (изъятие чужих земель, удлинение трасс), задержки сдачи объектов. Возможны техногенные истории на эксплуатации (нагонная волна без берегозащиты). При плохом сценарии — невозможность ПИР и СМР по линейке в окне 2026-10..2027-08.',
    'Подготовить и заключить договор на отдельный ППТ по магистральным сетям, либо встроить решение сетей в проекты отдельных объектов. Заключить допдоговор ТЗ-ЮГ с Заказчиком на сопровождение разработки ТЭО, ППТ и ПМТ под линейные объекты. Подготовить ТЗ силами отдела проектирования, выбрать исполнителя.',
    'Окно работ: окт.2026 — авг.2027. Подготовка договорной базы — сейчас, до начала Концепции',
    'open',
    'Аналитический отчёт ТЗ-ЮГ, март 2026, раздел 3.2 «ТЭО и ДПТ линейных (магистральных) сетей» + Таблица I «Дополнительные работы»'
),
-- ─── 3.3 Введение в эксплуатацию дороги ──────────────────────────────────
(
    'ROAD_TRANSFER',
    'Перенос автодороги Евпатория-Саки',
    'land_legal',
    'Стадия «Проект» по 8 отелям запланирована без единых кадастров и ГПЗУ. Эти документы появляются только после реализации проекта переноса дороги от РосАвтодор Ростов — то есть проект дороги становится единым gating-фактором для всей косы.',
    'Автомобильная трасса Евпатория-Саки проходит по части участков застройки. Перенос за полотно ж/д ведёт «РосАвтодор Ростов»; этот проект влияет на ППТ Инвестиционных участков (ООО «Визавир»). Документы на землю (кадастры, ГПЗУ) формируются через согласование градостроительной документации, реализацию переноса дороги и получение единых кадастров. Передаваемая подрядчикам документация сейчас базируется на предварительных материалах ППТ — границы и вертикальная планировка могут затронуть проекты.',
    'Без переноса дороги нет кадастров → нет ГПЗУ → нельзя начать стадию Проект на 8 объектах одновременно. Задержка дороги транслируется в задержку всего проекта. Дополнительный риск — корректировки ППТ затронут уже разработанный Форэскиз, потребуют переделки границ участков и точек стыковки с дублёром.',
    'Определить проект дороги как ключевой gating-фактор. Ускорить получение проекта от РосАвтодор Ростов. Отслеживать корректировки ППТ Инвестиционных участков, синхронизировать с подрядчиками отелей до завершения Форэскиза.',
    'Критическая точка — вход в стадию Проект (без ГПЗУ невозможен)',
    'open',
    'Аналитический отчёт ТЗ-ЮГ, март 2026, раздел 3.3 «Введение в эксплуатацию дороги»'
),
-- ─── 3.4 Переход на стадию Концепции ──────────────────────────────────────
(
    'CONCEPT_TRANSITION',
    'Переход с Форэскиза на Концепцию без потери сроков',
    'contracting',
    'Окончание форэскизных договоров намечено на октябрь-ноябрь 2026, но перечень потенциальных подрядчиков на Концепцию не определён, договорная основа не готовится. Без предварительного отбора и оформления — простой между стадиями со срывом инвестиционного плана.',
    'Сейчас на Форэскизе работают 4 организации: Хэдс Групп, ИП Акулова (8D), MLA+, Бюро 82. Договоры на стадию Концепция отсутствуют. Объём работ и требования к команде на Концепции выше, чем на Форэскизе; быстрая мобилизация без подготовки приводит либо к выбору неоптимальных подрядчиков, либо к задержке старта.',
    'Простой между стадиями = смещение всего инвестиционного плана. Если переход не подготовить — придётся либо растянуть Форэскиз и опоздать на Концепцию, либо начинать Концепцию на ходу с риском разрыва связности проектных решений. Дальнейшие стадии Проект и Экспертиза тоже сдвинутся.',
    'Предварительно провести отбор проектных организаций на Концепцию. Подготовить договорную основу с учётом необходимости сокращения сроков. Обеспечить переход с Форэскиза на Концепцию без потери темпа. Аналогичная работа потребуется при переходе Концепция → Проект.',
    'Крайний срок: окт-ноя 2026 (окончание форэскизных договоров)',
    'open',
    'Аналитический отчёт ТЗ-ЮГ, март 2026, раздел 3.4 «Переход на стадию Концепции»'
),
-- ─── 3.5 Утверждение графика проектирования ───────────────────────────────
(
    'SCHEDULE_GOVERNANCE',
    'Утверждение графика проектирования и процедуры его изменения',
    'organization',
    'Перт-график построен и увязан с инвестиционным планом, но формально не утверждён, процедура его изменения не согласована. Без этого график остаётся рабочим инструментом ТЗ, а не общим контрактом сторон проекта.',
    'Сформирован перт-график выполнения основных работ, включая контрольные даты ТЭПов, утверждения концепций, экспертизы, РНС. Управление сроками идёт через корректировку ленточного графика (точка оценки — дата получения РНС). График позволяет принимать решения о компромиссах: за счёт каких этапов или ресурсов компенсировать изменения. Однако формального утверждения графика как обязательного для всех сторон нет.',
    'Без утверждения и регламента изменения каждая сторона ведёт «свой» график. Конфликты сроков всплывают на стыках; компенсационные решения принимаются хаотично. Управленческое преимущество перт-графика теряется.',
    'Утвердить перт-график на нужном уровне управления (внутри ТЗ-ЮГ, с Заказчиком, с подрядчиками — выбрать). Согласовать процедуру внесения изменений. Зафиксировать как обязательный референс для оценки отклонений.',
    'До завершения Форэскиза',
    'open',
    'Аналитический отчёт ТЗ-ЮГ, март 2026, раздел 3.5 «Утверждение графика проектирования»'
),
-- ─── 3.6 Программа изысканий ──────────────────────────────────────────────
(
    'SURVEYS',
    'Программа инженерных изысканий с опережением графика',
    'engineering',
    'Изыскания (ИГДИ, ИГИ, ИГМИ, ИЭИ) нужны не только формально для экспертизы по ПП №87 — данные по нагонным явлениям и геологии должны попасть в проектные решения уже на Концепции, иначе закладываются риски задержек и удорожания.',
    'Состав изысканий: инженерно-геодезические (ИГДИ), инженерно-геологические (ИГИ), инженерно-гидрометеорологические (ИГМИ — включая рекогносцировку нагонных явлений), инженерно-экологические (ИЭИ). На стадии Форэскиз 8 объектов изыскания пока не запущены как программа — ведутся точечно. Без сводных данных по нагонной волне и геологии нельзя проектировать берегозащиту и инженерную защиту территории.',
    'Если изыскания не опередят ГР ПЗР — на стадии Проект и Экспертизы выявятся пробелы, придётся возвращаться назад. Особенно критично по нагонной волне: без её модели проект берегозащиты невозможен, а без берегозащиты эксплуатация отелей под угрозой.',
    'Запустить изыскания с опережением ГР ПЗР. Выполнить объём работ по ПП №87 для прохождения строительной экспертизы. Учесть результаты на стадии предпроектных предложений 8 объектов. Выработать программу инженерной защиты территории.',
    'Опережение графика проектирования (т.е. до перехода в Концепцию)',
    'open',
    'Аналитический отчёт ТЗ-ЮГ, март 2026, раздел 3.6 «Программа изысканий» + Таблица II «Инженерные изыскания»'
),
-- ─── 3.7 Орг.структура и персонал ─────────────────────────────────────────
(
    'PERSONNEL',
    'Кадровый рост ТЗ к стадиям Концепция и Проект',
    'personnel',
    'Текущие 3 сотрудника отдела ТЗ закроют Форэскиз, но к стадии Проект потребность в 5 раз больше — 16 специалистов на косу. Разовый набор в окне перехода не реалистичен; нужна плановая работа за 6 месяцев до пика.',
    'Сейчас в отделе технического сопровождения 3 человека: технический эксперт, технологический эксперт, руководитель отдела. На стадии Форэскиз состав достаточен с привлечением внешних специалистов. Объём работ растёт скачком: при переходе в Концепцию — кратно, при переходе в Проект — ещё ×2 (по 2 специалиста на объект × 8 = 16 + руководитель + 2 делопроизводителя). Разовый набор в стрессовом окне 2-3 месяца невозможен без потерь по качеству, срокам или стоимости.',
    'Невозможность набрать 13+ специалистов в окне перехода → срыв сроков Проекта по нескольким объектам одновременно. Альтернатива — компромисс по качеству при экстренном найме → ошибки технадзора всплывут на экспертизе. Третий сценарий — перегрузка действующих 3 сотрудников → выгорание и потеря ключевых людей.',
    'График поиска, подбора и адаптации персонала, привязанный к перт-графику Проекта. Структура работ и форматы исполнения (офис/дистанция/проект); механизмы взаимного привлечения сотрудников смежных отделов. Орг.структура, штатное и заштатное расписание ТЗ-ЮГ с функциями и полномочиями. Структура управляющих механизмов и автоматизация процессов.',
    'Окна найма: до окт-ноя 2026 (Концепция) и далее ровно перед Проектом',
    'open',
    'Аналитический отчёт ТЗ-ЮГ, март 2026, раздел 3.7 «Орг. структура тех. заказчика и персонал»'
),
-- ─── ППТ магистралей (доп. работы вне ГР РП ЗПР) ──────────────────────────
(
    'PPT_LINEAR',
    'Внесение изменений в ППТ под линейные объекты инженерной инфраструктуры',
    'land_legal',
    'Прокладка магистральных сетей возможна только при юридическом выделении земельных участков под коридоры трасс. Без отдельного ППТ/ПМТ под линейные объекты подключения зависят от чужих собственников — стоимость и сроки непредсказуемы.',
    'Технико-экономическое обоснование (ТЭО) под линейные объекты: водоснабжение, водоотведение, электроснабжение, газоснабжение, ливневая канализация, телефония, берегоукрепление, пешеходные переходы через ж/д и автотрассу. Текущий ППТ Инвестиционных участков не покрывает коридоры под инженерные сети. Юридическое выделение земельных участков под трассы не выполнено, постановка на баланс энергоснабжающим организациям не начата. Эта работа не входит в график РП ЗПР — нужен отдельный пакет.',
    'Без выделения коридоров: неопределённость технической возможности подключения к магистралям (земли иных собственников/арендаторов); удорожание (изъятие участков, удлинение трасс); удлинение сроков сдачи; изменение проектов отелей под границы коридоров; отсутствие пешеходных связей с автопарковкой; техногенные истории на эксплуатации; невозможность ПИР и СМР линейки.',
    'Юридическое выделение земельных участков под инженерную инфраструктуру. Заключение допдоговора ТЗ-ЮГ с Заказчиком на сопровождение работ по разработке ТЭО, ППТ и ПМТ под линейные объекты. Подготовка отделом проектирования ТЗ-ЮГ технического задания для разработки ТЭО, ППТ и ПМТ; определение сроков и стоимости. Выбор исполнителя и заключение контракта.',
    'До начала линейных работ (окт.2026) должны быть выделены коридоры',
    'open',
    'Аналитический отчёт ТЗ-ЮГ, март 2026, Таблица I «Дополнительные работы, не включённые в график РП ЗПР»'
);

